TLM.f("Sancti/05-10o",{"officium":"Ss. Gordiani and Epimachi Martyrum","rule":["vide C3;"],"fallback":"Commune/C3","from":{"Introitus":"Commune/C3","Graduale":"Commune/C3","Tractus":"Commune/C3","Evangelium":"Commune/C3","Offertorium":"Commune/C3","Communio":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 78:11-12; 78:10"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."},{"k":"ref","la":"Ps 78:1"},{"k":"text","la":"Deus, venérunt gentes in hereditátem tuam: polluérunt templum sanctum tuum: posuérunt Jerúsalem in pomórum custódiam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."}],"Oratio":[{"k":"text","la":"Da, quǽsumus, omnípotens Deus: ut, qui beatórum Mártyrum tuórum Gordiáni et Epímachi solémnia cólimus, eórum apud te intercessiónibus adjuvémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Apocalýpsis beáti Joánnis Apóstoli"},{"k":"ref","la":"Apoc 19:1-9"},{"k":"text","la":"In diébus illis: Post hæc ego Joánnes audívi quasi vocem turbárum multárum in cœlo, dicéntium: Allelúja: salus et glória et virtus Deo nostro est: quia vera et justa judícia sunt ejus, qui judicávit de meretríce magna, quæ corrúpit terram in prostitutióne sua, et vindicávit sánguinem servórum suórum de mánibus ejus. Et íterum dixérunt: Allelúja. Et fumus ejus ascéndit in sǽcula sæculórum. Et cecidérunt senióres vigínti quátuor et quátuor animália, et adoravérunt Deum sedéntem super thronum, dicéntes: Amen, Allelúja, tit vox de throno exívit, dicens: Laudem dícite Deo nostro, omnes servi ejus; et, qui timétis eum, pusílli et magni. Et audívi quasi vocem turbæ magnæ, et sicut vocem aquárum multárum, et sicut vocem tonitruórum magnórum, dicentium: Alleiúja: quóniam regnávit Dóminus, Deus noster omnípotens. Gaudeámus et exsultémus et demus glóriam ei: quia venérunt núptiæ Agni et uxor ejus præparávit se. Et datum est illi, ut coopériat se býssina splendénti et cándido. Býssinum enim justificatiónes sunt Sanctórum. Et dixit mihi: Scribe: Beáti, qui ad cœnam nuptiárum Agni vocáti sunt."}],"Graduale":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Eccl 44:14"},{"k":"text","la":"Córpora Sanctórum in pace sepúlta sunt, et nómina eórum vivent in generatiónem et generatiónem. Allelúja."}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 21:9-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Cum audiéritis prǽlia et seditiónes, nolíte terréri: opórtet primum hæc fíeri, sed nondum statim finis. Tunc dicébat illis: Surget gens contra gentem, et regnum advérsus regnum. Et terræmótus magni erunt per loca, et pestiléntiæ, et fames, terrorésque de coelo, et signa magna erunt. Sed ante hæc ómnia injícient vobis manus suas, et persequéntur tradéntes in synagógas et custódias, trahéntes ad reges et praesides propter nomen meum: contínget autem vobis in testimónium. Pónite ergo in córdibus vestris non præmeditári, quemádmodum respondeátis. Ego enim dabo vobis os et sapiéntiam, cui non potérunt resístere et contradícere omnes adversárii vestri. Tradémini autem a paréntibus, et frátribus, et cognátis, et amícis, et morte affícient ex vobis: et éritis ódio ómnibus propter nomen meum: et capíllus de cápite vestro non períbit. In patiéntia vestra possidébitis ánimas vestras."}],"Offertorium":[{"k":"ref","la":"Ps 67:36"},{"k":"text","la":"Mirábilis Deus in Sanctis suis: Deus Israël, ipse dabit virtútem et fortitúdinem plebi suæ: benedíctus Deus, allelúja."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, beatórum Martyrum tuórum Gordiáni et Epímachi dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Sap 3:4-6"},{"k":"text","la":"Et si coram homínibus torménta passi sunt, Deus tentávit eos: tamquam aurum in fornáce probávit eos, et quasi holocáusta accépit eos."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut, qui cœléstia aliménta percépimus, intercedéntibus sanctis Martýribus tuis Gordiáno et Epímacho, per hæc contra ómnia advérsa muniámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"3a56afb474695876":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da nas koji slavimo svetkovinu blaženih mučenika tvojih Gordijana i Epimaha pomaže kod tebe njihov zagovor.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"d12ca3bb9ca77760":{"t":"Dobrostivo primi, Gospodine:, prinose koje ti posvećujemo po zaslugama blaženih Gordijana i Epimaha, tvojih mučenika, i daj da nam postanu trajna pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"2689741a67640817":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da nas nebeska hrana koju smo primili zagovorom svetih tvojih mučenika Gordijana i Epimaha zaštiti od svih protivnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:1-7"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ego sum vitis vera: et Pater meus agrícola est. Omnem pálmitem in me non feréntem fructum, tollet eum: et omnem, qui fert fructum, purgábit eum, ut fructum plus áfferat. Jam vos mundi estis propter sermónem, quem locútus sum vobis. Manéte in me: et ego in vobis. Sicut palmes non potest ferre fructum a semetípso, nisi mánserit in vite: sic nec vos, nisi in me manséritis. Ego sum vitis, vos pálmites: qui manet in me, et ego in eo, hic fert fructum multum: quia sine me nihil potéstis fácere. Si quis in me non mánserit, mittétur foras sicut palmes, et aréscet, et cólligent eum, et in ignem mittent, et ardet. Si manséritis in me, et verba mea in vobis mánserint: quodcúmque voluéritis, petétis, et fiet vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}]}}});
